<?php /** @var int $schoolId */ /** @var array $features */ ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>School Entitlements · EduSasa</title><style>body{font-family:system-ui,sans-serif;margin:0;background:#f5f7fb;color:#172033}main{max-width:1200px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px;border-bottom:1px solid #eee}input{padding:8px;border:1px solid #d0d5dd;border-radius:7px;width:100%;box-sizing:border-box}button{padding:8px 12px;border:0;border-radius:7px;background:#172033;color:#fff}.muted{color:#667085}</style></head><body><main><h1>School #<?= (int)$schoolId ?> entitlements</h1><p class="muted">Overrides are applied only to this school and can expire automatically.</p><div class="card"><table><thead><tr><th>Module</th><th>Feature</th><th>Plan</th><th>Override</th><th>Limits</th><th>Reason</th><th>Expiry</th><th></th></tr></thead><tbody><?php foreach($features as $f): ?><tr><td><?= htmlspecialchars((string)$f['module_code']) ?></td><td><?= htmlspecialchars((string)$f['name']) ?><br><small><?= htmlspecialchars((string)$f['code']) ?></small></td><td><?= htmlspecialchars((string)($f['plan_code']??'—')) ?></td><td><input id="e<?= (int)$f['id'] ?>" type="checkbox" <?= $f['override_enabled']!==null && (int)$f['override_enabled']===1?'checked':'' ?>></td><td><input id="l<?= (int)$f['id'] ?>" value="<?= htmlspecialchars((string)($f['override_limits']??'')) ?>" placeholder='{"max":100}'></td><td><input id="r<?= (int)$f['id'] ?>" value="<?= htmlspecialchars((string)($f['reason']??'')) ?>"></td><td><input id="x<?= (int)$f['id'] ?>" type="datetime-local" value="<?= $f['expires_at']?htmlspecialchars(str_replace(' ','T',substr((string)$f['expires_at'],0,16))):'' ?>"></td><td><button type="button" onclick="save(<?= (int)$f['id'] ?>)">Save</button></td></tr><?php endforeach; ?></tbody></table></div></main><script>async function save(feature){let raw=document.getElementById('l'+feature).value,limits=null;if(raw.trim()){try{limits=JSON.parse(raw)}catch(e){alert('Limits must be valid JSON');return}}const body={feature_id:feature,enabled:document.getElementById('e'+feature).checked,limits,reason:document.getElementById('r'+feature).value,expires_at:document.getElementById('x'+feature).value};const r=await fetch('/platform/schools/<?= (int)$schoolId ?>/entitlements',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!d.success)alert(d.message||'Unable to save');else location.reload()}</script></body></html>
